def parse_records(text):
    lines=text.splitlines()
    out=[]
    for l in lines:
        if '#' in l: continue  # BUG: treats any '#' as a whole-line comment
        out.append(l.strip())  # BUG: destroys surrounding whitespace
    return [x for x in out if x]  # blank lines stay excluded (intended)
